/// C implementations of standard library functions declared with `@extern_c_indirect`.#include <inttypes.h>#include <stddef.h>#include <stdlib.h>/// Allocates `n` bytes of heap memory and sets `results to the allocation's address, /// or 0 on failure.void c_malloc_indirect(intptr_t const* n, void** result){  *result = malloc((size_t)(*n));  // TODO accept `size_t` (UInt) parameter.}/// Deallocates heap memory at `address`./// /// - Requires: there is a live heap allocation starting at `address`.void c_free_indirect(void** address){  free(*address);}// --------------------- TEMPORARY -------------------#include <stdio.h>void print_intptr_indirect(intptr_t const *x) { printf("%ld", (long)(*x)); fflush(stdout); }void print_u32_indirect(uint32_t const *x) { printf("%d", *x); fflush(stdout); }void print_u16_indirect(uint16_t const *x) { printf("%d", *x); fflush(stdout);}void print_long_indirect(long const *x) { printf("%ld", *x); fflush(stdout);}void print_newline_indirect() { printf("\n"); fflush(stdout);}void print_space_indirect() { printf(" "); fflush(stdout);}void print_comma_indirect() { printf(","); fflush(stdout);}void print_size_indirect(uint32_t const *x) { printf("size: %d", *x); fflush(stdout);}void print_alignment_indirect(uint16_t const *x) { printf("alignment: %d", *x); fflush(stdout);}